/**
 * Pure tests for the S5b triage context assembly.
 *
 * The oracle fixture is generated by `apps/crq-python/triage_context_vectors.py`
 * from the PRODUCTION Python `crq_repair.triage.context`. Every repository
 * read (carry, tree entries, blobs, grep, history) is an injected, retained
 * fact; the test compares the packed context, the ordered reads and the
 * recorded failure class, so the window, truncation, contract, content search,
 * escalation excerpts, evaluation order and refusals move only when Python
 * moves.
 *
 * No process, filesystem write, provider, judge or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  assembleTriageContext,
  TriageContextFailure,
  TriageContextRefusal,
  triageContextPreparer,
  triageContextToPlain,
  type TriageContextFailureType,
  type TriageContextReads,
} from '../../../src/policy/crq/triageContext.js';
import { planTriageDryRun, type TriageRepo } from '../../../src/policy/crq/triagePlan.js';
import { JsonObject, parseJsonValue, type JsonValue } from '../../../src/policy/crq/jsonValue.js';

interface Spec {
  row: Record<string, unknown>;
  tip: string;
  escalate: boolean;
  carry: { path: string | null; lines: number[] };
  entries: Record<string, Record<string, string>>;
  blobs: Record<string, string>;
  grep: string;
  history: string;
  failures: Record<string, string>;
}

interface Case {
  name: string;
  input: Spec;
  ts_refuses: boolean;
  raises?: string;
  error?: { type: string };
  result?: Record<string, unknown>;
  calls: unknown[][];
}

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/crq-triage-context/cases.json',
  import.meta.url,
);

const fixture = JSON.parse(readFileSync(FIXTURE_URL, 'utf8')) as {
  schema: string;
  cases: Case[];
};

function json(value: unknown): JsonValue {
  return parseJsonValue(JSON.stringify(value));
}

function object(value: unknown): JsonObject {
  const parsed = json(value);
  if (!(parsed instanceof JsonObject)) throw new Error('fixture value is not an object');
  return parsed;
}

function bytes(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, 'base64'));
}

/** The oracle records the carried lines expanded and sorted; expand the ranges alike. */
function expand(ranges: readonly (readonly [number, number])[]): number[] {
  const lines = new Set<number>();
  for (const [start, end] of ranges) {
    for (let line = start; line <= end; line += 1) lines.add(line);
  }
  return [...lines].sort((a, b) => a - b);
}

const FAILURE_TYPES: ReadonlySet<string> = new Set<TriageContextFailureType>([
  'KeyError',
  'TypeError',
  'ValueError',
  'IntegrityError',
  'CalledProcessError',
  'TimeoutExpired',
  'OSError',
]);

function failure(name: string): TriageContextFailure {
  if (!FAILURE_TYPES.has(name)) throw new Error(`unknown failure class ${name}`);
  return new TriageContextFailure(name as TriageContextFailureType);
}

function replayReads(spec: Spec, calls: unknown[][]): TriageContextReads {
  const maybeFail = (key: string): void => {
    const name = spec.failures[key];
    if (name !== undefined) throw failure(name);
  };
  return {
    carry: (target, tip, path, ranges) => {
      calls.push(['carry', target, tip, path, expand(ranges)]);
      maybeFail('carry');
      return { path: spec.carry.path, lines: new Set(spec.carry.lines) };
    },
    entries: (commit) => {
      calls.push(['entries', commit]);
      maybeFail(`entries:${commit}`);
      const tree = spec.entries[commit];
      if (tree === undefined) throw new Error(`unscripted entries ${commit}`);
      return new Map(Object.entries(tree));
    },
    blob: (oid) => {
      calls.push(['blob', oid]);
      maybeFail(`blob:${oid}`);
      const content = spec.blobs[oid];
      if (content === undefined) throw new Error(`unscripted blob ${oid}`);
      return bytes(content);
    },
    grep: (needle, tip, path) => {
      calls.push(['grep', needle, tip, path]);
      maybeFail('grep');
      return bytes(spec.grep);
    },
    history: (range, path) => {
      calls.push(['history', range, path]);
      maybeFail('history');
      return bytes(spec.history);
    },
  };
}

function request(spec: Spec): Parameters<typeof assembleTriageContext>[1] {
  const row = object(spec.row);
  const recovered = row.get('recovered_anchor');
  return {
    row,
    tip: spec.tip,
    escalate: spec.escalate,
    recoveredAnchor: recovered instanceof JsonObject ? recovered : null,
  };
}

type Outcome =
  | { kind: 'result'; value: Record<string, unknown> }
  | { kind: 'failure'; type: string }
  | { kind: 'refusal' };

function run(spec: Spec, calls: unknown[][]): Outcome {
  try {
    const context = assembleTriageContext(replayReads(spec, calls), request(spec));
    return { kind: 'result', value: triageContextToPlain(context) };
  } catch (error) {
    if (error instanceof TriageContextFailure) return { kind: 'failure', type: error.pythonType };
    if (error instanceof TriageContextRefusal) return { kind: 'refusal' };
    throw error;
  }
}

describe('triage context assembly: differential against crq_repair.triage.context', () => {
  test('the fixture is the schema this test reads', () => {
    expect(fixture.schema).toBe('cq.crq-triage-context-vector/v1');
    expect(fixture.cases.length).toBeGreaterThan(150);
  });

  for (const item of fixture.cases) {
    test(item.name, () => {
      const calls: unknown[][] = [];
      const outcome = run(item.input, calls);
      if (item.raises !== undefined || item.ts_refuses) {
        // Python aborts the run (or is lenient where the port is deliberately
        // stricter): the port refuses rather than recording a row error.
        expect(outcome.kind).toBe('refusal');
        return;
      }
      if (item.error !== undefined) {
        expect(outcome).toEqual({ kind: 'failure', type: item.error.type });
      } else {
        expect(outcome).toEqual({ kind: 'result', value: item.result });
      }
      expect(calls).toEqual(item.calls);
    });
  }
});

describe('triage context preparer seam', () => {
  const ready = fixture.cases.find((c) => c.name === 'anchored-window-around-carried-lines');
  const caught = fixture.cases.find((c) => c.error?.type === 'OSError');
  const refused = fixture.cases.find((c) => c.raises !== undefined);
  if (ready === undefined || caught === undefined || refused === undefined) {
    throw new Error('fixture lacks a seam case');
  }

  test('a complete context is ready and is handed to the observer', () => {
    const seen: string[] = [];
    const outcome = triageContextPreparer(replayReads(ready.input, []), (context) => {
      seen.push(context.currentPath);
    })(request(ready.input));
    expect(outcome).toEqual({ kind: 'ready' });
    expect(seen).toEqual([ready.input.carry.path]);
  });

  test('a failure Python records becomes a row error naming the class', () => {
    const outcome = triageContextPreparer(replayReads(caught.input, []))(request(caught.input));
    expect(outcome).toEqual({ kind: 'error', errorType: 'OSError' });
  });

  test('a condition Python does not catch propagates instead of becoming a row error', () => {
    const prepare = triageContextPreparer(replayReads(refused.input, []));
    expect(() => prepare(request(refused.input))).toThrow(TriageContextRefusal);
  });

  test('an unexpected exception is never swallowed', () => {
    const reads: TriageContextReads = {
      ...replayReads(ready.input, []),
      entries: () => {
        throw new RangeError('boom');
      },
    };
    expect(() => triageContextPreparer(reads)(request(ready.input))).toThrow(RangeError);
  });

  test('the planner records a context failure as a row error through the preparer', () => {
    const row = object(ready.input.row);
    const repo: TriageRepo = {
      beginInvocation: () => undefined,
      commitDate: () => '2026-01-01T00:00:00+00:00\n',
      entryPaths: () => new Set([ready.input.carry.path as string]),
      lineage: () => null,
      provenDeleted: () => false,
      deletingCommit: () => '\n',
    };
    const calls: unknown[][] = [];
    const plan = (reads: TriageContextReads) =>
      planTriageDryRun({
        rows: [row],
        reviews: [],
        tip: ready.input.tip,
        maximum: 10,
        seconds: 1000,
        clock: () => 0,
        repo,
        prepareContext: triageContextPreparer(reads),
      });
    const failing = plan({
      ...replayReads(ready.input, calls),
      carry: (...args) => {
        calls.push(['carry', args[0]]);
        throw failure('OSError');
      },
    });
    expect(calls).toEqual([['carry', ready.input.row.target]]);
    expect(failing.report.contextErrors).toEqual([
      { findingId: 'f1', type: 'OSError', target: ready.input.tip },
    ]);

    const clean = plan(replayReads(ready.input, []));
    expect(clean.report.contextErrors).toEqual([]);
    expect(clean.report.judgmentCandidates).toEqual(['f1']);
  });
});
